/* Shared stylesheet for every lesson and reference sheet in this workspace. */
@import url("https://fonts.googleapis.com/css2?family=Source+Serif+4:ital,opsz,wght@0,8..60,400;0,8..60,600;1,8..60,400&family=JetBrains+Mono:wght@400;600&display=swap");

:root {
  --bg: #fffff8;
  --fg: #1d1d1b;
  --muted: #6b6b66;
  --rule: #d9d6c8;
  --accent: #a3301e;
  --accent-soft: #f4e3dc;
  --ok: #2f6b3a;
  --ok-soft: #e1efe3;
  --bad: #9b2c2c;
  --bad-soft: #f6e0e0;
  --panel: #f6f4ea;
  --serif: "Source Serif 4", Georgia, serif;
  --mono: "JetBrains Mono", ui-monospace, monospace;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #1b1b19; --fg: #e9e7df; --muted: #a09d92; --rule: #3a3934;
    --accent: #e0846f; --accent-soft: #3a2621; --ok: #8fc99a; --ok-soft: #1f3324;
    --bad: #ec9a9a; --bad-soft: #3b2222; --panel: #24241f;
  }
}

* { box-sizing: border-box; }
body {
  margin: 0; background: var(--bg); color: var(--fg);
  font: 400 1.15rem/1.6 var(--serif);
}
main { max-width: 42rem; margin: 0 auto; padding: 3rem 1rem 5rem; }

h1 { font-weight: 400; font-size: 2.2rem; line-height: 1.2; margin: 0 0 .25rem; }
h2 { font-weight: 400; font-style: italic; font-size: 1.5rem; margin: 2.75rem 0 .5rem; }
h3 { font-weight: 600; font-size: 1.05rem; margin: 1.75rem 0 .25rem; }
p, li { margin: .6rem 0; }
a { color: var(--accent); text-underline-offset: 2px; }
code, .mono { font-family: var(--mono); font-size: .85em; }
.subtitle { color: var(--muted); font-style: italic; margin: 0 0 2rem; }
.crumbs { font-size: .9rem; color: var(--muted); margin-bottom: 2rem; }
.crumbs a { color: var(--muted); }
hr { border: 0; border-top: 1px solid var(--rule); margin: 2.5rem 0; }

/* Key idea callout */
.key {
  border-left: 3px solid var(--accent); padding: .25rem 0 .25rem 1rem; margin: 1.5rem 0;
  font-size: 1.2rem;
}
.formula { text-align: center; font-size: 1.35rem; margin: 1.25rem 0; }

/* Sidenote-style citation, inline on narrow screens */
.cite { font-size: .85rem; color: var(--muted); }

table { border-collapse: collapse; width: 100%; margin: 1rem 0; font-size: 1rem; }
th, td { text-align: left; padding: .4rem .6rem; border-bottom: 1px solid var(--rule); }
th { font-weight: 600; }
td.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }

.panel { background: var(--panel); border: 1px solid var(--rule); border-radius: 6px; padding: 1rem 1.25rem; margin: 1.5rem 0; }
.panel h3 { margin-top: 0; }

/* Free-recall prompt: answer hidden until the learner commits */
details.recall { background: var(--panel); border: 1px solid var(--rule); border-radius: 6px; padding: .75rem 1rem; margin: 1rem 0; }
details.recall summary { cursor: pointer; font-weight: 600; }
details.recall summary::after { content: " (try in your head first, then open)"; font-weight: 400; color: var(--muted); font-size: .9rem; }

/* Quiz (see quiz.js) */
.quiz { border: 1px solid var(--rule); border-radius: 6px; padding: 1rem 1.25rem; margin: 1.5rem 0; }
.quiz .q { font-weight: 600; margin-top: 0; }
.quiz ol { list-style: none; padding: 0; margin: .5rem 0; }
.quiz button.opt {
  display: block; width: 100%; text-align: left; margin: .4rem 0; padding: .55rem .8rem;
  font: inherit; font-size: 1rem; color: var(--fg); background: var(--bg);
  border: 1px solid var(--rule); border-radius: 4px; cursor: pointer;
}
.quiz button.opt:hover:not(:disabled) { border-color: var(--accent); }
.quiz button.opt.right { background: var(--ok-soft); border-color: var(--ok); }
.quiz button.opt.wrong { background: var(--bad-soft); border-color: var(--bad); }
.quiz .why { display: none; color: var(--muted); font-size: 1rem; }
.quiz.done .why { display: block; }

/* Ask-your-teacher reminder and source box */
.aside { font-size: 1rem; background: var(--accent-soft); border-radius: 6px; padding: .75rem 1rem; margin: 2rem 0; }

footer.nav { display: flex; justify-content: space-between; gap: 1rem; font-size: .95rem; margin-top: 3rem; border-top: 1px solid var(--rule); padding-top: 1rem; }

@media print {
  :root { --bg: #fff; --fg: #000; --panel: #fff; }
  main { max-width: none; padding: 0; }
  .quiz, details.recall, .widget, .aside, footer.nav { break-inside: avoid; }
  details.recall > * { display: block; }
  a { color: inherit; }
}

// Turns <figure class="quiz"> blocks into instant-feedback multiple choice.
// Markup: <p class="q">, <ol> of <li> (mark the right one with data-correct), <p class="why">.
document.querySelectorAll("figure.quiz").forEach((quiz) => {
  const list = quiz.querySelector("ol");
  const items = [...list.children];
  for (let i = items.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [items[i], items[j]] = [items[j], items[i]];
  }
  list.replaceChildren(
    ...items.map((li) => {
      const btn = document.createElement("button");
      btn.className = "opt";
      btn.type = "button";
      btn.innerHTML = li.innerHTML;
      const correct = li.hasAttribute("data-correct");
      btn.addEventListener("click", () => {
        if (correct) {
          btn.classList.add("right");
          quiz.classList.add("done");
          quiz.querySelectorAll("button.opt").forEach((b) => (b.disabled = true));
        } else {
          btn.classList.add("wrong");
          btn.disabled = true;
        }
      });
      const wrap = document.createElement("li");
      wrap.append(btn);
      return wrap;
    }),
  );
});

// Interactive Kraft budget + binary code tree. Mount: <div class="widget code-tree" data-lengths="1,2,3,3"></div>
(() => {
  const MAX_LEN = 5;
  const SVG = "http://www.w3.org/2000/svg";

  const style = document.createElement("style");
  style.textContent = `
    .code-tree { border: 1px solid var(--rule); border-radius: 6px; padding: 1rem 1.25rem; margin: 1.5rem 0; }
    .code-tree label { font-weight: 600; font-size: 1rem; }
    .code-tree input { font: inherit; font-family: var(--mono); font-size: 1rem; width: 100%; padding: .4rem .6rem;
      margin: .35rem 0 .75rem; color: var(--fg); background: var(--bg); border: 1px solid var(--rule); border-radius: 4px; }
    .code-tree .bar { display: flex; height: 1.4rem; border: 1px solid var(--fg); border-radius: 3px; overflow: hidden; position: relative; }
    .code-tree .seg { border-right: 1px solid var(--bg); background: var(--accent); opacity: .85; }
    .code-tree .seg.over { background: var(--bad); }
    .code-tree .sum { font-family: var(--mono); font-size: .95rem; margin: .5rem 0; }
    .code-tree .verdict { font-weight: 600; }
    .code-tree .verdict.ok { color: var(--ok); } .code-tree .verdict.bad { color: var(--bad); }
    .code-tree svg { width: 100%; height: auto; display: block; margin-top: .5rem; }
    .code-tree svg line { stroke: var(--rule); stroke-width: 1.5; }
    .code-tree svg circle { fill: var(--bg); stroke: var(--muted); stroke-width: 1.2; }
    .code-tree svg circle.blocked { fill: var(--panel); stroke: var(--rule); }
    .code-tree svg circle.word { fill: var(--accent); stroke: var(--accent); }
    .code-tree svg text { font-family: var(--mono); font-size: 11px; fill: var(--fg); text-anchor: middle; }
    .code-tree svg text.edge { fill: var(--muted); font-size: 10px; }
    .code-tree .legend { font-size: .85rem; color: var(--muted); }`;
  document.head.append(style);

  const frac = (l) => `1/${2 ** l}`;

  // Canonical prefix code: assign codewords in order of increasing length.
  function assign(lengths) {
    const order = lengths.map((l, i) => [l, i]).sort((a, b) => a[0] - b[0]);
    const words = [];
    let code = 0, prev = order[0][0];
    for (const [l, i] of order) {
      code <<= l - prev;
      words[i] = code.toString(2).padStart(l, "0");
      code += 1;
      prev = l;
    }
    return words;
  }

  function el(tag, attrs, parent) {
    const n = document.createElementNS(SVG, tag);
    for (const k in attrs) n.setAttribute(k, attrs[k]);
    parent.append(n);
    return n;
  }

  function drawTree(svg, words) {
    svg.replaceChildren();
    const depth = Math.max(...words.map((w) => w.length));
    const W = 600, rowH = 52, top = 16;
    svg.setAttribute("viewBox", `0 0 ${W} ${top * 2 + depth * rowH}`);
    const pos = (d, k) => [((k + 0.5) / 2 ** d) * W, top + d * rowH];
    const set = new Set(words);
    const isWord = (bits) => set.has(bits);
    const isBlocked = (bits) => words.some((w) => bits.length > w.length && bits.startsWith(w));
    const label = (d, k) => (d === 0 ? "" : k.toString(2).padStart(d, "0"));

    for (let d = 1; d <= depth; d++)
      for (let k = 0; k < 2 ** d; k++) {
        const [x, y] = pos(d, k), [px, py] = pos(d - 1, k >> 1);
        el("line", { x1: px, y1: py, x2: x, y2: y }, svg);
        if (d <= 3) {
          const t = el("text", { x: (x + px) / 2 + (k & 1 ? 7 : -7), y: (y + py) / 2, class: "edge" }, svg);
          t.textContent = k & 1;
        }
      }
    for (let d = 0; d <= depth; d++)
      for (let k = 0; k < 2 ** d; k++) {
        const bits = label(d, k), [x, y] = pos(d, k);
        const cls = isWord(bits) && d > 0 ? "word" : isBlocked(bits) ? "blocked" : "";
        el("circle", { cx: x, cy: y, r: cls === "word" ? 7 : 4, class: cls }, svg);
        if (cls === "word") {
          const t = el("text", { x, y: y - 11 }, svg);
          t.textContent = bits;
        }
      }
  }

  document.querySelectorAll(".code-tree").forEach((root) => {
    root.innerHTML = `
      <label>Codeword lengths (comma-separated, 1–${MAX_LEN})
        <input type="text" spellcheck="false" value="${root.dataset.lengths || "1,2,3,3"}"></label>
      <div class="bar" aria-hidden="true"></div>
      <div class="sum"></div>
      <div class="verdict" aria-live="polite"></div>
      <svg role="img" aria-label="Binary code tree"></svg>
      <div class="legend">Filled dot = codeword. Pale dots below it are blocked: using them would break the prefix rule.</div>`;
    const input = root.querySelector("input"), bar = root.querySelector(".bar"),
      sum = root.querySelector(".sum"), verdict = root.querySelector(".verdict"), svg = root.querySelector("svg");

    function render() {
      const lengths = input.value.split(/[\s,]+/).filter(Boolean).map(Number);
      if (!lengths.length || lengths.some((l) => !Number.isInteger(l) || l < 1 || l > MAX_LEN)) {
        verdict.className = "verdict bad";
        verdict.textContent = `Enter whole numbers from 1 to ${MAX_LEN}.`;
        return;
      }
      const total = lengths.reduce((s, l) => s + 2 ** -l, 0);
      bar.replaceChildren(...lengths.map((l, i) => {
        const s = document.createElement("div");
        const used = lengths.slice(0, i).reduce((a, x) => a + 2 ** -x, 0);
        s.className = "seg" + (used + 2 ** -l > 1 + 1e-9 ? " over" : "");
        s.style.width = `${(2 ** -l / Math.max(1, total)) * 100}%`;
        return s;
      }));
      sum.textContent = `K = ${lengths.map(frac).join(" + ")} = ${+total.toFixed(4)}`;
      if (total > 1 + 1e-9) {
        verdict.className = "verdict bad";
        verdict.textContent = "Over budget: no prefix code has these lengths.";
        svg.replaceChildren();
        return;
      }
      const words = assign(lengths);
      verdict.className = "verdict ok";
      verdict.textContent = (total < 1 - 1e-9 ? "Fits, with budget left over: " : "Fits exactly: ") + words.join("  ");
      drawTree(svg, words);
    }
    input.addEventListener("input", render);
    render();
  });
})();

